vec2 sdVoronoi_hash2(in vec2 p)
{
    // procedural white noise	
	return fract(sin(vec2(dot(p,vec2(127.1,311.7)),dot(p,vec2(269.5,183.3))))*43758.5453);
}

float sdVoronoi(in SDFG_VEC p, in float scale, in float thickness, in float animOffset)
{
    vec2 scaledP = scale * p.xz;
    vec2 ip = floor(scaledP);
    vec2 fp = fract(scaledP);

    //----------------------------------
    // first pass: regular voronoi
    //----------------------------------
	vec2 mg, mr;

    float md = 8.0;
    for( int j=-1; j<=1; j++ )
    for( int i=-1; i<=1; i++ )
    {
        vec2 g = vec2(float(i),float(j));
		vec2 o = sdVoronoi_hash2( ip + g );
		//#ifdef ANIMATE
        o = 0.5 + 0.5*sin( animOffset + 6.2831*o );
        //#endif	
        vec2 r = g + o - fp;
        float d = dot(r,r);

        if( d<md )
        {
            md = d;
            mr = r;
            mg = g;
        }
    }

    //----------------------------------
    // second pass: distance to borders
    //----------------------------------
    md = 8.0;
    for( int j=-2; j<=2; j++ )
    for( int i=-2; i<=2; i++ )
    {
        vec2 g = mg + vec2(float(i),float(j));
		vec2 o = sdVoronoi_hash2( ip + g );
		//#ifdef ANIMATE
        o = 0.5 + 0.5*sin( animOffset + 6.2831*o );
        //#endif	
        vec2 r = g + o - fp;

        if( dot(mr-r,mr-r)>0.00001 )
            md = min( md, dot( 0.5*(mr+r), normalize(r-mr) ) );
    }

    //return vec3( md, mr );
    return md - thickness;
}
